# BATCH_APPEND_MARKER

with open(CATALOG) as f:
    data = json.load(f)

added, skipped = 0, 0
for key, vals in T.items():
    if key in data['strings']:
        skipped += 1
        continue
    data['strings'][key] = {
        'localizations': {
            lang: {'stringUnit': {'state': 'translated', 'value': v}}
            for lang, v in zip(LANGS, vals)
        }
    }
    added += 1

with open(CATALOG, 'w') as f:
    json.dump(data, f, ensure_ascii=False, indent=2)
    f.write('\n')

print(f'added: {added}, skipped(existing): {skipped}, total keys: {len(data["strings"])}')
